from pathlib import Path
from PIL import Image,ImageDraw,ImageFont
import json,base64,html,zipfile
from openpyxl import load_workbook
R=Path('/home/user/moko');P=R/'production';E=R/'releases/release02';E.mkdir(parents=True,exist_ok=True)
rows=json.load(open(R/'catalog/registry.json'));lookup={a['id']:a for a in rows}
first=['b5zjy0PHU0s','EsLUSn9RDL4','tXsjlxHMt6Y','nnktD99huyE','feEv04DYWbA','ex8ibsNSCiA']
b2=[a['id'] for a in json.load(open(R/'batch02/new_items.json'))];b3=[a['id'] for a in json.load(open(R/'batch03/new_items.json'))];order=first+b2+b3
assert len(order)==18 and len(set(order))==18
cards=[]
for i,vid in enumerate(order):
 a=lookup[vid];p=P/'thumbnails'/(vid+'.jpg');img=Image.open(p);assert img.size==(1280,720) and p.stat().st_size<2_000_000
 uri='data:image/jpeg;base64,'+base64.b64encode(p.read_bytes()).decode()
 label='Согласованный образец' if i<6 else 'Партия 02 · проверить' if i<12 else 'Партия 03 · описания и главы проверены'
 cards.append(f'<article data-batch="{3 if i>=12 else 2 if i>=6 else 1}"><button class="pic" onclick="show({i})" aria-label="{html.escape(a["headline"])}"><img src="{uri}" alt="{html.escape(a["headline"])}"></button><h2>{i+1:02} / {html.escape(a["headline"])}</h2><p style="color:{a["color"]}">{html.escape(a["visual"])}</p><p>{label}</p><button onclick="show({i})">Открыть крупно</button></article>')
page='''<!doctype html><html lang="ru"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>MOKO · Партия 03</title><style>*{box-sizing:border-box}body{margin:0;background:#080d15;color:#f5f7fb;font:15px/1.5 system-ui,sans-serif}header,main,footer{max-width:1500px;margin:auto;padding:25px}.k{color:#ed6262;letter-spacing:2px;font-size:12px}h1{font-size:clamp(28px,4vw,43px);line-height:1.1}p{color:#a3aebe}header p{max-width:880px}main{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:29px 22px}button{font:inherit;background:#172233;border:1px solid #334156;border-radius:8px;color:white;padding:8px 13px;cursor:pointer}button.active{background:#e1e9f5;color:#0b1220}.tabs{display:flex;gap:9px;margin-top:20px;flex-wrap:wrap}.pic{padding:0;border:0;display:block;width:100%;overflow:hidden}img{width:100%;display:block}h2{font-size:19px;margin:12px 0 4px}article p{font-size:13px;margin:4px 0 10px}dialog{padding:15px;background:#0b1220;border:1px solid #334156;border-radius:12px;color:white;width:min(1320px,96vw);max-height:95vh}dialog::backdrop{background:#000d}.dh{display:flex;justify-content:space-between;gap:20px;align-items:center;margin-bottom:14px}.dh h2{margin:0}a{color:#a7c9ff}.small{font-size:12px}article[hidden]{display:none}@media(max-width:1050px){main{grid-template-columns:1fr 1fr}}@media(max-width:640px){main{grid-template-columns:1fr}header,main,footer{padding:18px}}</style><header><div class="k">MOKO / SYSTEMS · ПАРТИЯ 03</div><h1>Следующие шесть уроков Python</h1><p>Сначала проверены описания автора и главы с таймкодами. Stage — типы сообщений; Messenger — диалоговые окна; Driver — обмен с приборами. Это не полный просмотр видео. Согласованные обложки не изменены.</p><div class="tabs"><button class="active" id="new" onclick="filter(true)">Новая партия · 6</button><button id="all" onclick="filter(false)">Все подготовленные · 18</button></div></header><main>'''+''.join(cards)+'''</main><footer><p class="small">Подготовлено 18 из 94: 6 согласованных образцов и 12 новых макетов для проверки. В очереди 74 обычных видео и 2 Shorts. На YouTube ничего не загружено. Иллюстрации партии 03 — условные схемы, не точные интерфейсы. Весь файл работает без интернета.</p></footer><dialog id="dlg"><div class="dh"><h2 id="title"></h2><button onclick="document.getElementById('dlg').close()" aria-label="Закрыть">×</button></div><img id="image"><p><a id="download">Скачать JPG · 1280 × 720</a></p></dialog><script>const titles='''+json.dumps([lookup[v]['headline'] for v in order],ensure_ascii=False)+''';const ids='''+json.dumps(order)+''';function show(i){let pic=document.querySelectorAll('.pic img')[i];document.getElementById('title').textContent=titles[i];document.getElementById('image').src=pic.src;document.getElementById('image').alt=titles[i];let dl=document.getElementById('download');dl.href=pic.src;dl.download=ids[i]+'.jpg';document.getElementById('dlg').showModal()}function filter(only){document.querySelectorAll('article').forEach(e=>e.hidden=only&&e.dataset.batch!=='3');document.getElementById('new').classList.toggle('active',only);document.getElementById('all').classList.toggle('active',!only)}filter(true)</script></html>'''
(E/'preview_18.html').write_text(page)
(E/'README.txt').write_text('MOKO · выпуск 02\n18 горизонтальных JPG: 6 согласованных, 12 новых.\nВ очереди 74 обычных видео + 2 Shorts. На YouTube файлы не загружены.\n\nНовая партия 03: уроки Python 0.1, 1, 2, 3, 4, 6.\nИмена файлов совпадают с YouTube ID. В docs — актуальные версии 1.1.\nСтарые JPG первой и второй партии не изменены.\nИсследовательские заметки описывают проверку смысла по описаниям и главам, не полный просмотр роликов.\n')
with zipfile.ZipFile(E/'MOKO_Выпуск_02_18_обложек.zip','w',zipfile.ZIP_DEFLATED) as z:
 for vid in order:z.write(P/'thumbnails'/(vid+'.jpg'),'thumbnails/'+vid+'.jpg')
 for file in ['MOKO_Правила_обложек_v1.1.docx','MOKO_Сводная_карта_плейлистов_v1.1.docx','MOKO_Реестр_94_видео_и_плейлисты_v1.1.xlsx','MOKO_Реестр_94_видео_v1.1.csv']:z.write(R/'docs'/file,'docs/'+file)
 z.write(E/'preview_18.html','preview_18.html');z.write(E/'README.txt','README.txt');z.write(R/'batch03/batch03_preview.jpg','batch03_preview.jpg');z.write(R/'batch03/research/review_notes.md','review_notes.md')
wb=load_workbook(R/'docs/MOKO_Реестр_94_видео_и_плейлисты_v1.1.xlsx');assert wb['Видео'].max_row==95 and wb['Готовые файлы'].max_row==19
assert len([a for a in rows if a['status']=='В очереди'])==74
print('QA: 18 images 1280x720 and <2MB; registry 94 videos/18 files. ZIP:',(E/'MOKO_Выпуск_02_18_обложек.zip').stat().st_size)
